import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if rho == 0.0:
                radius = min(a, b)
            else:
                ux, uy = u / rho, v / rho
                radius = 1.0 / math.sqrt((ux / a) ** 2 + (uy / b) ** 2)
            d = (1.0 - rho) * radius
            t = max(0.0, min(1.0, d + 0.5))
            out.append(amp * t)
    return out

def encode(img):
    # Use the brighter pixels to initialize center and ellipse shape.
    pts = []
    sw = sx = sy = 0.0
    for i in range(16):
        for j in range(16):
            w = max(0.0, img[i * 16 + j] - 0.25)
            if w:
                pts.append((i, j, w))
                sw += w
                sx += w * j
                sy += w * i

    if sw == 0.0:
        return [7.5, 7.5, 2.5, 2.0, 0.0, 0.8]

    cx, cy = sx / sw, sy / sw
    xx = yy = xy = 0.0
    for i, j, w in pts:
        dx, dy = j - cx, i - cy
        xx += w * dx * dx
        yy += w * dy * dy
        xy += w * dx * dy
    xx, yy, xy = xx / sw, yy / sw, xy / sw
    angle = 0.5 * math.atan2(2.0 * xy, xx - yy)
    disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
    l1 = max(0.5, 0.5 * (xx + yy + disc))
    l2 = max(0.5, 0.5 * (xx + yy - disc))
    a = max(1.3, min(5.0, 2.0 * math.sqrt(l1)))
    b = max(1.3, min(5.0, 2.0 * math.sqrt(l2)))
    amp = max(0.55, min(1.05, max(img)))

    def loss(p):
        pred = _render(*p)
        return sum((x - y) ** 2 for x, y in zip(img, pred))

    p = [cx, cy, a, b, angle, amp]
    steps = [0.8, 0.8, 0.7, 0.7, 0.25, 0.12]
    best = loss(p)

    # Direct coordinate search fits the rendered ellipse to the noisy pixels.
    for _ in range(24):
        changed = False
        for k in range(6):
            for sign in (-1.0, 1.0):
                q = p[:]
                q[k] += sign * steps[k]
                if k in (2, 3):
                    q[k] = max(1.2, min(5.2, q[k]))
                elif k == 5:
                    q[k] = max(0.45, min(1.1, q[k]))
                elif k == 4:
                    q[k] = (q[k] + math.pi / 2) % math.pi - math.pi / 2
                val = loss(q)
                if val < best:
                    p, best, changed = q, val, True
        if not changed:
            steps = [s * 0.58 for s in steps]
            if max(steps) < 0.012:
                break
    return p

def decode(z):
    return _render(*z)
